        (0xf9ff49179c943172e9e9bd7ea779f4d4618b579309f9b62fe73bc10594878bbd),
        (0xfa2920bbd4026b94902f10db0f9c998af76cd6099292288c74641ac1233efa3f),
        (0xfae6c3ab2c5169cb12df49111d35526375d9fe79b765d7b5ea1dbed512672799),
        (0xfc96234b0779d947fa6f59ca272aa654b4d1c4ca8c9a739473d6df096b8e3972),
        (0xfdce043f44772ea1332dd9f8542bd184ec1581d808b06b5d24b31eaa82acbc15),
        (0xfe83838e00f473d8aaaea5775b0634127254f973edcbf0de3ffc4c4a540f51eb),
        (0xfedd2b84989db2c2b988ea60e79980fbeaec730a89f8115db2eed6ca7d8ffb3e),
        (0xfeefcca9e313fc864ac908c2b5dc3b932fddc56e93a121f23e7854d72c2f7204),
        (0xff245b20e5e62c9b5be8b14f3aecac88b34688fb2b3a48364ada57d9430d4d35)
)
SELECT
    CONCAT('0x', TO_HEX(t.hash)) AS tx_hash,
    CONCAT('0x', TO_HEX(t."from")) AS transaction_sender,
    CONCAT('0x', TO_HEX(t."to")) AS transaction_recipient,
    t.success,
    t.gas_limit,
    t.gas_used,
    t.gas_price,
    t.max_fee_per_gas,
    t.max_priority_fee_per_gas,
    t.priority_fee_per_gas,
    t.block_time,
    t.block_number,
    t.block_date,
    t.index AS transaction_index
FROM ethereum.transactions t
JOIN selected_hashes h ON t.hash = h.tx_hash
WHERE (
        t.block_date >= DATE '2023-02-01' AND t.block_date < DATE '2023-02-10'
    AND t.block_time >= TIMESTAMP '2023-02-01 00:00:00' AND t.block_time < TIMESTAMP '2023-02-10 00:00:00'
) OR (
        t.block_date >= DATE '2022-06-13' AND t.block_date < DATE '2022-06-22'
    AND t.block_time >= TIMESTAMP '2022-06-13 00:00:00' AND t.block_time < TIMESTAMP '2022-06-22 00:00:00'
)
